<script setup lang="ts">
import {
  ClearOutlined,
  DeleteOutlined,
  EditOutlined,
  PlusOutlined,
  ReloadOutlined,
  SearchOutlined,
} from '@ant-design/icons-vue';
import { useAccess } from '@vben/access';
import { message, Modal, type FormInstance } from 'ant-design-vue';
import { computed, onMounted, reactive, ref } from 'vue';

import {
  createFile,
  deleteFile,
  getFileList,
  updateFile,
  type File,
  type FilePayload,
} from '#/api/kadmin/generated/file';

type TablePagination = { current?: number; pageSize?: number };

const { hasAccessByCodes } = useAccess();
const canCreate = computed(() => hasAccessByCodes(['system:file:create', '*']));
const canUpdate = computed(() => hasAccessByCodes(['system:file:update', '*']));
const canDelete = computed(() => hasAccessByCodes(['system:file:delete', '*']));

const loading = ref(false);
const errorText = ref('');
const items = ref<File[]>([]);
const total = ref(0);
const page = ref(1);
const pageSize = ref(20);

const filters = reactive<Record<string, string>>({
  fileName: '',
  fileUrl: '',
  fileFormat: '',
  fileSchool: '',
  fileSubject: '',
  reviewer: '',
  createBy: '',
  createTime: '',
  updateBy: '',
  updateTime: '',
  remark: '',
});

const columns = [
  { title: 'File Id', dataIndex: 'fileId', key: 'fileId', width: 160, ellipsis: true },
  { title: 'User Id', dataIndex: 'userId', key: 'userId', width: 160, ellipsis: true },
  { title: 'File Name', dataIndex: 'fileName', key: 'fileName', width: 160, ellipsis: true },
  { title: '文件URL：minioUrl/bucket/objectName，bucket 沿用 ptmj', dataIndex: 'fileUrl', key: 'fileUrl', width: 160, ellipsis: true },
  { title: 'File Size', dataIndex: 'fileSize', key: 'fileSize', width: 160, ellipsis: true },
  { title: 'File Format', dataIndex: 'fileFormat', key: 'fileFormat', width: 160, ellipsis: true },
  { title: 'File Year', dataIndex: 'fileYear', key: 'fileYear', width: 160, ellipsis: true },
  { title: '文件类型：1-期末，2-期中，3-资料，4-补考，5-其他学校', dataIndex: 'fileType', key: 'fileType', width: 160, ellipsis: true },
  { title: 'File School', dataIndex: 'fileSchool', key: 'fileSchool', width: 160, ellipsis: true },
  { title: 'File Subject', dataIndex: 'fileSubject', key: 'fileSubject', width: 160, ellipsis: true },
  { title: 'Reviewer', dataIndex: 'reviewer', key: 'reviewer', width: 160, ellipsis: true },
  { title: '文件状态：0-未审核，1-通过，2-未通过，3-被举报', dataIndex: 'fileStatus', key: 'fileStatus', width: 160, ellipsis: true },
  { title: '删除标记：0-未删除，1-已删除', dataIndex: 'delFlag', key: 'delFlag', width: 160, ellipsis: true },
  { title: 'Create By', dataIndex: 'createBy', key: 'createBy', width: 160, ellipsis: true },
  { title: 'Create Time', dataIndex: 'createTime', key: 'createTime', width: 160, ellipsis: true },
  { title: 'Update By', dataIndex: 'updateBy', key: 'updateBy', width: 160, ellipsis: true },
  { title: 'Update Time', dataIndex: 'updateTime', key: 'updateTime', width: 160, ellipsis: true },
  { title: '备注（复用为 MinIO 文件夹相对路径）', dataIndex: 'remark', key: 'remark', width: 160, ellipsis: true },
  { title: '操作', key: 'action', width: 120, fixed: 'right' },
];

const pagination = computed(() => ({
  current: page.value,
  pageSize: pageSize.value,
  pageSizeOptions: ['10', '20', '50', '100'],
  showSizeChanger: true,
  showTotal: (value: number) => `共 ${value} 条`,
  total: total.value,
}));

async function fetchList() {
  loading.value = true;
  errorText.value = '';
  try {
    const result = await getFileList({
      page: page.value,
      pageSize: pageSize.value,
      fileName: filters.fileName || undefined,
      fileUrl: filters.fileUrl || undefined,
      fileFormat: filters.fileFormat || undefined,
      fileSchool: filters.fileSchool || undefined,
      fileSubject: filters.fileSubject || undefined,
      reviewer: filters.reviewer || undefined,
      createBy: filters.createBy || undefined,
      createTime: filters.createTime || undefined,
      updateBy: filters.updateBy || undefined,
      updateTime: filters.updateTime || undefined,
      remark: filters.remark || undefined,
    });
    items.value = result.items;
    total.value = result.total;
  } catch (error) {
    errorText.value = error instanceof Error ? error.message : '加载失败';
  } finally {
    loading.value = false;
  }
}

function search() {
  page.value = 1;
  void fetchList();
}

function resetSearch() {
  filters.fileName = '';
  filters.fileUrl = '';
  filters.fileFormat = '';
  filters.fileSchool = '';
  filters.fileSubject = '';
  filters.reviewer = '';
  filters.createBy = '';
  filters.createTime = '';
  filters.updateBy = '';
  filters.updateTime = '';
  filters.remark = '';
  search();
}

function handleTableChange(paginationValue: TablePagination) {
  page.value = paginationValue.current ?? 1;
  pageSize.value = paginationValue.pageSize ?? 20;
  void fetchList();
}

const modalOpen = ref(false);
const submitting = ref(false);
const editingId = ref<null | number>(null);
const formRef = ref<FormInstance>();
const dirty = ref(false);

const formState = reactive<Record<string, any>>({
  fileName: '',
  fileUrl: '',
  fileSize: undefined,
  fileFormat: '',
  fileYear: undefined,
  fileType: undefined,
  fileSchool: '',
  fileSubject: '',
  reviewer: '',
  fileStatus: undefined,
  delFlag: undefined,
  createBy: '',
  createTime: '',
  updateBy: '',
  updateTime: '',
  remark: '',
});

const rules: Record<string, unknown> = {
  fileName: [{ required: true, message: '请输入File Name', trigger: 'blur' }],
  fileUrl: [{ required: true, message: '请输入文件URL：minioUrl/bucket/objectName，bucket 沿用 ptmj', trigger: 'blur' }],
  fileSubject: [{ required: true, message: '请输入File Subject', trigger: 'blur' }],
};

function openCreate() {
  editingId.value = null;
  dirty.value = false;
  formState.fileName = '';
  formState.fileUrl = '';
  formState.fileSize = undefined;
  formState.fileFormat = '';
  formState.fileYear = undefined;
  formState.fileType = undefined;
  formState.fileSchool = '';
  formState.fileSubject = '';
  formState.reviewer = '';
  formState.fileStatus = undefined;
  formState.delFlag = undefined;
  formState.createBy = '';
  formState.createTime = '';
  formState.updateBy = '';
  formState.updateTime = '';
  formState.remark = '';
  modalOpen.value = true;
}

async function openEdit(record: File) {
  editingId.value = record.fileId;
  dirty.value = false;
  formState.fileName = record.fileName;
  formState.fileUrl = record.fileUrl;
  formState.fileSize = record.fileSize;
  formState.fileFormat = record.fileFormat;
  formState.fileYear = record.fileYear;
  formState.fileType = record.fileType;
  formState.fileSchool = record.fileSchool;
  formState.fileSubject = record.fileSubject;
  formState.reviewer = record.reviewer;
  formState.fileStatus = record.fileStatus;
  formState.delFlag = record.delFlag;
  formState.createBy = record.createBy;
  formState.createTime = record.createTime;
  formState.updateBy = record.updateBy;
  formState.updateTime = record.updateTime;
  formState.remark = record.remark;
  modalOpen.value = true;
}

function requestClose() {
  if (!dirty.value) {
    modalOpen.value = false;
    return;
  }
  Modal.confirm({
    title: '放弃修改？',
    content: '当前表单有未保存的修改。',
    okText: '放弃',
    okType: 'danger',
    cancelText: '继续编辑',
    onOk: () => {
      dirty.value = false;
      modalOpen.value = false;
    },
  });
}

function markDirty() {
  if (modalOpen.value) {
    dirty.value = true;
  }
}

async function submit() {
  try {
    await formRef.value?.validate();
  } catch {
    return;
  }
  submitting.value = true;
  try {
    const payload = {
      fileName: formState.fileName,
      fileUrl: formState.fileUrl,
      fileSize: formState.fileSize,
      fileFormat: formState.fileFormat,
      fileYear: formState.fileYear,
      fileType: formState.fileType,
      fileSchool: formState.fileSchool,
      fileSubject: formState.fileSubject,
      reviewer: formState.reviewer,
      fileStatus: formState.fileStatus,
      delFlag: formState.delFlag,
      createBy: formState.createBy,
      createTime: formState.createTime,
      updateBy: formState.updateBy,
      updateTime: formState.updateTime,
      remark: formState.remark,
    } as FilePayload;
    if (editingId.value === null) {
      await createFile(payload);
      message.success('新增成功');
    } else {
      await updateFile(editingId.value, payload);
      message.success('修改成功');
    }
    modalOpen.value = false;
    dirty.value = false;
    await fetchList();
  } catch (error) {
    message.error(error instanceof Error ? error.message : '提交失败');
  } finally {
    submitting.value = false;
  }
}

async function remove(record: File) {
  try {
    await deleteFile(record.fileId);
    message.success('删除成功');
    await fetchList();
  } catch (error) {
    message.error(error instanceof Error ? error.message : '删除失败');
  }
}

onMounted(() => {
  void fetchList();
});
</script>
